    # cells of cluster C (abs coords) compared against D shifted by (dr,dc)
    Ds = {(a+dr,b+dc) for a,b in D}
    miss=[]; bad=False
    for (a,b) in C:
        if (a+dr,b+dc) in Ds:
            if g[a][b] != g[a+dr][b+dc]: bad=True
        elif g[a+dr][b+dc]!=0 and g[a][b]==0:
